y *<input class="form-control" id="external-quantity" type="number" min="0.01" step="0.01" name="external_quantity" value="<?= e($externalPart['quantity']??'1') ?>"></label></div><div class="external-only"><label class="form-label">Buying Price *<input class="form-control" id="external-buying-price" type="number" min="0" step="0.01" name="external_unit_cost" value="<?= e($externalPart['buying_price']??'0') ?>"></label></div><div class="external-only"><label class="form-label">Selling Price *<input class="form-control" type="number" min="0" step="0.01" name="external_selling_price" value="<?= e($externalPart['selling_price']??'0') ?>"></label></div><div class="general-only"><label class="form-label">Amount (Rs.) *<input class="form-control" type="number" min="0.01" step="0.01" name="items[0][unit_price]" id="general-amount" value="<?= e($input['items'][0]['unit_price']??'0') ?>" required><input type="hidden" name="items[0][name]" value="General Expense"><input type="hidden" name="items[0][quantity]" value="1"></label></div><div class="external-only"><label class="form-label">Total Cost<input class="form-control" id="external-total-cost" readonly value="0.00"></label></div><div class="full expense-payment-heading"><h2>3. Payment</h2><p>Choose a status or enter the amount still due.</p></div><div><label class="form-label">Payment Method *<select class="form-select" name="payment_method"><option value="cash" <?= $input['payment_method']==='cash'?'selected':'' ?>>Cash</option><option value="card" <?= $input['payment_method']==='card'?'selected':'' ?>>Card</option><option value="bank" <?= $input['payment_method']==='bank'?'selected':'' ?>>Bank Transfer</option><option value="other" <?= $input['payment_method']==='other'?'selected':'' ?>>Other</option></select></label></div><div><label class="form-label">Payment Status *</label><div class="expense-payment-options compact"><label><input type="radio" name="payment_terms" value="cash" <?= $input['payment_terms']==='cash'?'checked':'' ?>> Paid</label><label><input type="radio" name="payment_terms" value="credit" <?= $input['payment_terms']==='credit'?'checked':'' ?>> Due</label><label><input type="radio" name="payment_terms" value="partial" <?= $input['payment_terms']==='partial'?'checked':'' ?>> Partial</label></div></div><div class="partial-payment"><label class="form-label">Paid Amount (Rs.) *<input class="form-control" type="number" min="0" step="0.01" name="paid_amount" id="paid-amount" value="<?= e($input['paid_amount']) ?>"></label></div><div><label class="form-label">Due Amount (Rs.)<input class="form-control" id="due-amount" type="number" min="0" step="0.01" inputmode="decimal" aria-describedby="expense-due-help" value="0.00"></label><small id="expense-due-help">Enter the amount still unpaid. Paid amount and status will adjust automatically.</small></div><div class="full"><label class="form-label"><?= $external?'Supplier Bill / Invoice':'Bill / Receipt' ?> (Optional)<input class="form-control" type="file" name="bill_file" accept=".jpg,.jpeg,.png,.pdf"></label><small class="text-muted">JPG, JPEG, PNG or PDF (Max 5MB)</small></div><div class="full"><label class="form-label">Notes (Optional)<textarea class="form-control" name="notes" rows="3" maxlength="500"><?= e($input['notes']) ?></textarea></label></div></div></section>
<div class="expense-form-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=expenses">Cancel</a><button class="btn btn-light" name="status" value="draft">Save Draft</button><button class="btn btn-primary" type="submit">Save Expense</button></div></form>
<script>
document.addEventListener('DOMContentLoaded',function(){
const form=document.getElementById('expense-form'),amount=document.getElementById('general-amount'),qty=document.getElementById('external-quantity'),buy=document.getElementById('external-buying-price'),extTotal=document.getElementById('external-total-cost'),paid=document.getElementById('paid-amount'),due=document.getElementById('due-amount'),description=form.querySelector('[name="description"]');
if(description)description.required=false;
function isExternal(){return form.querySelector('input[name="expense_type"]:checked')?.value==='external_part'}
function update(event){
    const total=Math.max(0,isExternal()?(parseFloat(qty.value)||0)*(parseFloat(buy.value)||0):(parseFloat(amount.value)||0));
    extTotal.value=total.toFixed(2);due.max=total.toFixed(2);due.setCustomValidity('');
    let terms=form.querySelector('input[name="payment_terms"]:checked')?.value||'cash';
    if(event?.target===due){
        const value=Number(due.value);
        if(due.value===''||!Number.isFinite(value)||value<0||value>total){due.setCustomValidity('Enter a due amount between 0 and '+total.toFixed(2)+'.');return;}
        terms=value===0?'cash':value===total?'credit':'partial';
        form.querySelector('input[name="payment_terms"][value="'+terms+'"]').checked=true;
        paid.value=(total-value).toFixed(2);
    }else{
        const paidValue=terms==='cash'?total:terms==='credit'?0:Math.min(total,Math.max(0,parseFloat(paid.value)||0));
        due.value=Math.max(0,total-paidValue).toFixed(2);
        if(terms!=='partial')paid.value=paidValue.toFixed(2);
    }
    paid.closest('.partial-payment').style.display=terms==='partial'?'block':'none';
}
function toggle(){const ext=isExternal();document.querySelectorAll('.general-only').forEach(e=>e.hidden=ext);document.querySelectorAll('.external-only').forEach(e=>e.hidden=!ext);amount.disabled=ext;qty.disabled=!ext;buy.disabled=!ext;document.querySelectorAll('[name="supplier_id_external"],[name="job_card_id"],[name="external_part_name"],[name="external_selling_price"]').forEach(e=>e.disabled=!ext);amount.required=!ext;update();}
form.querySelectorAll('input[name="expense_type"],input[name="payment_terms"]').forEach(e=>e.addEventListener('change',toggle));
form.addEventListener('input',update);toggle();
});
</script>

</div>
